import React from "react";
import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
// Google Fonts Loader (Standard Protocol)
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type LuxuryVillaCarouselProps = Record<string, any>;

const LuxuryVillaCarousel: React.FC<LuxuryVillaCarouselProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 15,
  villaImages = [
    "https://images.unsplash.com/photo-1613490493576-7fde63acd811?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1564013799919-ab600027ffc6?q=80&w=800&auto=format&fit=crop",
  ],
  cardWidth = 500,
  cardHeight = 350,
  carouselRadius = 600,
  rotationSpeed = 0.5,
  cardBorderRadius = 24,
  shadowIntensity = 0.6,
  blurStrength = 4,
}) => {
  // Load standard fonts just in case, though not used for text here
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Global rotation of the carousel over time
  // One full rotation every (10 / rotationSpeed) seconds roughly
  const globalRotation = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 360 * rotationSpeed]
  );

  const count = villaImages.length;
  const angleStep = 360 / count;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        perspective: "1200px", // Essential for 3D effect
        overflow: "hidden",
      }}
    >
      <div
        style={{
          width: width,
          height: height,
          position: "relative",
          transformStyle: "preserve-3d",
        }}
      >
        {villaImages.map((src, index) => {
          // 1. Calculate base angle for this card
          const baseAngle = index * angleStep;
          
          // 2. Add global rotation to get current angle
          // We subtract globalRotation to spin the carousel "forward"
          const currentAngle = baseAngle - globalRotation;
          
          // 3. Normalize angle to -180...180 range to determine "frontness"
          const normalizedAngle = ((currentAngle % 360) + 360) % 360;
          const distanceToFront = Math.min(
            Math.abs(normalizedAngle - 0),
            Math.abs(normalizedAngle - 360)
          );

          // 4. Calculate visual properties based on angle
          // Blur increases as it moves away from 0deg (front)
          const blurAmount = interpolate(
            distanceToFront,
            [0, 90, 180],
            [0, blurStrength, blurStrength * 2],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Cards are now fully solid regardless of position
          const opacity = 1;

          // Scale down slightly in the back for depth enhancement
          const depthScale = interpolate(
            distanceToFront,
            [0, 180],
            [1, 0.8],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // 5. Entrance Animation (Pop up one by one)
          const staggerDelay = 8; // Frames between each card popping up
          const startFrame = index * staggerDelay;
          
          const popUpScale = spring({
            frame: frame - startFrame,
            fps,
            config: {
              damping: 12,
              stiffness: 100,
              mass: 0.8,
            },
          });

          // Combine depth scale and entrance scale
          const finalScale = depthScale * popUpScale;

          // 6. Calculate Shadow
          // Shadow is stronger when close to front, weaker in back
          const shadowOpacity = interpolate(
             distanceToFront,
             [0, 180],
             [shadowIntensity, 0]
          );
          
          return (
            <div
              key={index}
              style={{
                position: "absolute",
                width: cardWidth,
                height: cardHeight,
                left: (width - cardWidth) / 2,
                top: (height - cardHeight) / 2,
                transformStyle: "preserve-3d",
                transform: `
                  rotateY(${baseAngle - globalRotation}deg) 
                  translateZ(${carouselRadius}px) 
                  scale(${finalScale})
                `,
                borderRadius: cardBorderRadius,
                // Ensure proper 3D sorting (though preserve-3d handles most)
                zIndex: Math.round((180 - distanceToFront) * 10), 
              }}
            >
              {/* Image Container with Blur & Overflow Hidden for Rounded Corners */}
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: cardBorderRadius,
                  overflow: "hidden",
                  backgroundColor: "#000", // Fallback
                  boxShadow: `0px 20px 40px rgba(0,0,0,${shadowOpacity})`,
                  filter: `blur(${blurAmount}px)`,
                  opacity: opacity,
                  border: "1px solid rgba(255,255,255,0.1)", // Subtle border for luxury feel
                }}
              >
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              </div>
              
              {/* Reflection/Gloss effect (Optional luxury touch) */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  borderRadius: cardBorderRadius,
                  background: "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 50%)",
                  pointerEvents: "none",
                  opacity: interpolate(distanceToFront, [0, 90], [1, 0]), // Only visible on front cards
                }}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default LuxuryVillaCarousel;